  "type": "function",
  "function": {
      "name": "post_message",
      "description": "Post a message to a board you can read.",
      "parameters": {
          "type": "object",
          "properties": {
              "text": {
                  "type": "string",
                  "description": "Message text."
              },
              "channel": {
                  "type": "string",
